import{_ as e,o,c as t,a2 as r}from"./chunks/framework.Bg-Zxr5O.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Logical-Operators.md","filePath":"manual-zh/Logical-Operators.md","lastUpdated":1785684581000}'),c={name:"manual-zh/Logical-Operators.md"};function p(l,a,s,d,n,i){return o(),t("div",null,[...a[0]||(a[0]=[r('<h3 id="_7-5-logical-operators" tabindex="-1">7.5 Logical Operators <a class="header-anchor" href="#_7-5-logical-operators" aria-label="Permalink to &quot;7.5 Logical Operators&quot;">​</a></h3><p>逻辑运算符接受逻辑操作数并产生逻辑结果，即“真或假”。逻辑运算符并非真正的布尔运算符，因为它们也可能产生系统缺失值。更多信息参见 <a href="./Boolean-Values">Boolean Values</a>。</p><p><code>a AND b</code><code>a &amp; b</code></p><p>当 a 和 b 均为真时为真，否则为假。如果其中一个操作数为假，则结果为假，即使另一个为缺失。如果两个操作数均为缺失，则结果为缺失。</p><p><code>a OR b</code><code>a | b</code></p><p>当 a 和 b 中至少一个为真时为真。如果其中一个操作数为真，则结果为真，即使另一个操作数为缺失。如果两个操作数均为缺失，则结果为缺失。</p><p><code>NOT a</code><code>~ a</code></p><p>当 a 为假时为真。如果操作数为缺失，则结果为缺失。</p>',8)])])}const u=e(c,[["render",p]]);export{m as __pageData,u as default};
